_choice_pid() {
    command -v ps >/dev/null || return 0
    ps -eo pid=,comm= | gawk 'NF >= 2 {
        pid = $1
        sub(/^[[:space:]]*[^[:space:]]+[[:space:]]+/, "")
        print pid "\t" $0
    }'
}

_choice_sort_key() {
    htop --sort-key=help 2>/dev/null | gawk 'NF >= 2 {
        key = $1
        sub(/^[[:space:]]*[^[:space:]]+[[:space:]]+/, "")
        print key "\t" $0
    }'
}

_choice_user() {
    command -v ps >/dev/null || return 0
    ps -eo user= | sed -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//' -e '/^$/d'
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
